-    let trail_on = std::env::var("TRAIL_ON")
-        .map(|v| v != "0" && !v.eq_ignore_ascii_case("false"))
-        .unwrap_or(true);
-    let trail_atr_k: f64 = std::env::var("TRAIL_ATR_K")
-        .ok()
-        .and_then(|v| v.parse().ok())
-        .unwrap_or(1.5);
-    let trail_min_step: f64 = std::env::var("TRAIL_MIN_STEP")
