-    engine.executor.load_px_dec(&tick_cache_out);
-    // keşif şeridi: 0'a düşen stratejiler küçük lotla canlıda sınanır
-    let explore_on = std::env::var("ENGINE_EXPLORE")
-        .map(|v| v != "0" && !v.eq_ignore_ascii_case("off"))
