-                                           tracing::error!(
-                                               "WS FIRTINASI: {} kopma / 5 dk → kill YOK, ExitsOnly \
-                                                (giriş kapalı; çıkışlar + borsa stop açık)",
-                                               health.ws_recent()
-                                           );
-                                       }
-            // Exponential backoff before restart
-                                       let now = hyperliquid_api::now_ms();
